package com.hbm.entity.mob.maskman;
import com.hbm.entity.projectile.EntityBulletBaseNT;import com.hbm.registry.HbmSounds;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.entity.ai.goal.Goal;
/** Original attack switch deliberately adds nextInt(2), allowing the same attack to repeat. */
final class MaskManLaserGoal extends Goal {private enum Attack{ORB(60,5),MISSILE(10,10),SPLASH(40,3);final int delay,amount;Attack(int d,int a){delay=d;amount=a;}}private final MaskMan mob;private LivingEntity target;private Attack attack;private int timer,attackCount;MaskManLaserGoal(MaskMan mob){this.mob=mob;attack=Attack.values()[mob.getRandom().nextInt(3)];}@Override public boolean canUse(){var t=mob.getTarget();if(t==null)return false;target=t;return mob.position().distanceTo(t.position())>10;}@Override public boolean canContinueToUse(){return canUse()||!mob.getNavigation().isDone();}@Override public boolean requiresUpdateEveryTick(){return true;}@Override public void tick(){if(--timer<=0){timer=attack.delay;switch(attack){case ORB->{var orb=new EntityBulletBaseNT(mob.level(),LegacyNpcBullets.ORB,mob,target,2,0);orb.setDeltaMovement(orb.getDeltaMovement().add(0,.5,0));mob.level().addFreshEntity(orb);mob.playSound(HbmSounds.get("weapon.teslaShoot"),1,1);}case MISSILE->{var missile=new EntityBulletBaseNT(mob.level(),LegacyNpcBullets.ROCKET,mob,target,1,0);missile.setDeltaMovement((target.getX()-mob.getX())*.05,.5+mob.getRandom().nextDouble()*.5,(target.getZ()-mob.getZ())*.05);mob.level().addFreshEntity(missile);mob.playSound(HbmSounds.get("weapon.hkShoot"),1,1);}case SPLASH->{for(int i=0;i<5;i++)mob.level().addFreshEntity(new EntityBulletBaseNT(mob.level(),LegacyNpcBullets.TRACER,mob,target,1,.05F));}}if(++attackCount>=attack.amount){attackCount=0;attack=Attack.values()[(attack.ordinal()+mob.getRandom().nextInt(2))%3];}}mob.setYRot(mob.yHeadRot);}}
